function spawnFx(x,y,color,text){effects.push({x,y,color,text,born:clock});for(let i=0;i<6;i++)particles.push({x,y,vx:rnd(-45,45),vy:rnd(-70,0),color,life:.4,max:.4});if(effects.length>35)effects.shift()}
function dig(tx,ty){const t=tile(tx,ty);if(!t||!['dirt','rock','ore'].includes(t.k)||dist(p,center(tx,ty))>T*1.72)return false;if(t.k==='ore'&&bag.reduce((a,b)=>a+b,0)>=bagMax()){if(clock-lastBagToast>2){toast('가방이 가득 찼습니다. 마을로 귀환해 판매하세요.');lastBagToast=clock}return false}if(attackClock>0)return true;attackClock=interval();p.angle=Math.atan2((ty+.5)*T-p.y,(tx+.5)*T-p.x);if(Math.abs(Math.cos(p.angle))>.1)p.face=Math.cos(p.angle)>0?1:-1;const critical=Math.random()<critChance(),damage=Math.round(power()*(critical?1.8:1)*(blast?4:1));t.hp-=damage;spawnFx((tx+.5)*T,(ty+.5)*T,t.k==='ore'?ores[t.ore].color:'#c4b093',`${critical?'치명타 ':''}−${damage}`);tone();if(t.hp<=0){if(t.k==='ore'){const o=ores[t.ore],lucky=Math.random()<bonusChance(),amount=Math.min((t.core?5:t.rich?3:1)+(lucky?1:0),bagMax()-bag.reduce((a,b)=>a+b,0));const first=!save.collection[o.name];bag[t.ore]+=amount;runMined+=amount;save.total+=amount;save.xp+=Math.round((Math.ceil(o.value/8)*amount+(first?10:0))*(area==='astral'?1.3:1)*(1+save.stats.dexterity*.02));skillCharge=Math.min(100,skillCharge+12);if(level()>runMilestone){runMilestone=level();toast(`광부 Lv.${level()}! 성장 화면에서 스탯 포인트를 배분하세요.`)}save.collection[o.name]=(save.collection[o.name]||0)+amount;spawnFx((tx+.5)*T,(ty+.5)*T,o.color,`+${o.name}${amount>1?' ×'+amount:''}`);tone('ore');if(t.core){energy=Math.min(100,energy+12);toast(`광맥 원석 발견! ${o.name} ${amount}개와 배터리 12% 회복`)}else if(lucky)toast(`행운의 발견! ${o.name} ${amount}개 획득`);else if(t.rich)toast(`고품질 ${o.name} 광맥! ${amount}개 획득`)}t.k='air';t.hp=0;reveal();if(goal?.tx===tx&&goal?.ty===ty)goal=null;}return true}let lastBagToast=-10;
function pathTo(tx,ty){if(mode==='town')return townPath(tx,ty);if(tx<=0||ty<=0||tx>=gw-1||ty>=gh-1||!discovered[ty]?.[tx]){toast('밝혀진 곳을 선택하거나 드래그해서 새로운 길을 탐험하세요.');return}const target=tile(tx,ty);if(target.k==='bedrock')return;const sx=Math.floor(p.x/T),sy=Math.floor(p.y/T),open=[{x:sx,y:sy,g:0,f:0}],prev=new Map(),scores=new Map([[sx+','+sy,0]]);let end=null,iterations=0;while(open.length&&iterations++<gw*gh*3){open.sort((a,b)=>a.f-b.f);const q=open.shift(),key=q.x+','+q.y;if(q.g!==scores.get(key))continue;if(q.x===tx&&q.y===ty){end=q;break}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const x=q.x+dx,y=q.y+dy,t=tile(x,y);if(!t||t.k==='bedrock'||!discovered[y]?.[x])continue;const nkey=x+','+y,cost=q.g+1+(['dirt','rock','ore'].includes(t.k)?Math.ceil(t.hp/power())*2:0);if(cost<(scores.get(nkey)??Infinity)){scores.set(nkey,cost);prev.set(nkey,key);open.push({x,y,g:cost,f:cost+Math.abs(x-tx)+Math.abs(y-ty)})}}}if(!end){toast('이곳으로 갈 수 없습니다. 다른 위치를 선택하세요.');return}let out=[],key=tx+','+ty;while(key!==sx+','+sy){const [x,y]=key.split(',').map(Number);out.push({...center(x,y),tx:x,ty:y});key=prev.get(key);if(!key)break}route=out.reverse();goal={tx,ty,x:(tx+.5)*T,y:(ty+.5)*T};}
function townPath(x,y){x=clamp(x,45,1055);y=clamp(y,60,1000);const b=buildings.find(b=>x>b.x-20&&x<b.x+b.w+20&&y>b.y-20&&y<b.y+b.h+20);if(b){x=b.door.x;y=b.door.y}const S=25,sx=Math.floor(p.x/S),sy=Math.floor(p.y/S),tx=Math.floor(x/S),ty=Math.floor(y/S),queue=[{x:sx,y:sy}],prev=new Map([[sx+','+sy,null]]);let found=false;for(let i=0;i<queue.length;i++){const q=queue[i];if(q.x===tx&&q.y===ty){found=true;break}for(const [dx,dy] of [[1,0],[-1,0],[0,1],[0,-1]]){const nx=q.x+dx,ny=q.y+dy,key=nx+','+ny;if(nx<1||nx>42||ny<2||ny>39||prev.has(key)||!canStand((nx+.5)*S,(ny+.5)*S))continue;prev.set(key,q.x+','+q.y);queue.push({x:nx,y:ny})}}if(!found){toast('건물 앞의 길을 눌러 주세요.');return}let key=tx+','+ty,out=[];while(prev.get(key)){const [x,y]=key.split(',').map(Number);out.push({x:(x+.5)*S,y:(y+.5)*S});key=prev.get(key)}route=out.reverse();if(canStand(x,y))route.push({x,y});goal={x,y,building:b?.id};}
function autoTarget(){if(mode!=='mine')return null;const px=Math.floor(p.x/T),py=Math.floor(p.y/T);let opts=[];for(let y=py-1;y<=py+1;y++)for(let x=px-1;x<=px+1;x++){const t=tile(x,y);if(t&&['ore','dirt','rock'].includes(t.k)&&dist(p,center(x,y))<T*1.5){const a=Math.atan2((y+.5)*T-p.y,(x+.5)*T-p.x),delta=Math.abs(Math.atan2(Math.sin(a-p.angle),Math.cos(a-p.angle)));if(t.k==='ore'||delta<.7)opts.push({x,y,score:(t.k==='ore'?0:5)+delta})}}opts.sort((a,b)=>a.score-b.score);return opts[0]}
function nearest(){if(mode==='town'){const list=buildings.map(b=>({...b,d:dist(p,b.door)})).sort((a,b)=>a.d-b.d);return list[0].d<100?list[0]:null}const t=tile(Math.floor(p.x/T),Math.floor(p.y/T));if(t?.k==='stairs')return{id:'stairs',action:'다음 층으로 내려가기'};return null}
function interact(){if(paused)return;if(mode==='town'){if(near?.id==='mine')showMine();else if(near?.id==='gear')showShop();else if(near?.id==='market')showBag();else if(near?.id==='quest')showQuests();else if(near?.id==='inn')showIdle();else{showMine()}}else if(near?.id==='stairs')nextFloor();else{const a=autoTarget();if(a)dig(a.x,a.y);else toast('광석이나 벽 가까이에서 채굴할 수 있습니다.')}}
function openSheet(id,title,html){resetInput();openPanel=id;paused=true;$('sheetTitle').textContent=title;$('sheetBody').innerHTML=html;$('shade').hidden=false;$('sheet').scrollTop=0;$('close').focus({preventScroll:true})}function closeSheet(){openPanel=null;$('shade').hidden=true;manualPause=false;paused=false;resetInput()}
function showMine(){const a=mines.find(a=>a.id===selectedMine)||mines[0],allowed=mineUnlocked(a),depth=Math.min(200,depthFor(a.id));openSheet('mine','탐험할 광산 선택',`<p class="intro">광산마다 만나는 광물과 탐험 혜택이 다릅니다. 입장료는 없습니다.</p><div class="mine-prep" style="--mine-color:${a.theme[1]}"><div class="mine-title">${mineIcon(a)}<div><span class="tag">선택한 광산</span><h2>${a.name}</h2><p>${a.special}</p></div></div><div class="prep-row"><label for="floorSelect">출발 층</label><select id="floorSelect">${Array.from({length:depth},(_,i)=>`<option value="${i+1}" ${i+1===depth?'selected':''}>지하 ${i+1}층</option>`).join('')}</select><span>채굴력 ${power()} / 가방 ${bagMax()}칸</span></div><button class="primary" data-act="start" ${!allowed||mode!=='town'?'disabled':''}>${mode!=='town'?'마을에서 출발할 수 있습니다':allowed?a.name+' 탐험 시작':'해금 조건을 달성해 주세요'}</button></div><div class="mine-list">${mines.map(m=>{const unlocked=mineUnlocked(m);return`<article class="mine-card ${m.id===selectedMine?'selected':''} ${unlocked?'':'locked'}" style="--mine-color:${m.theme[1]};--mine-ground:${m.theme[0]}">${mineIcon(m)}<div><h3>${m.name}${save.mineClears[m.id]?' <span class="tag">돌파 완료</span>':''}</h3><p>${m.label}</p><p class="mine-benefit">${m.special}</p><small>${unlocked?`최고 개방 ${depthFor(m.id)}층 / `:'해금: '}Lv.${m.level}${unlocked?'':` (현재 ${level()})`} / 누적 ${m.total}개${unlocked?'':` (현재 ${save.total}개)`}</small></div><button class="secondary" data-mine="${m.id}" ${!unlocked||m.id===selectedMine?'disabled':''}>${!unlocked?'잠김':m.id===selectedMine?'선택됨':'선택'}</button></article>`}).join('')}</div><p class="note">광산별 개방 층이 따로 저장됩니다. 각 광산의 3층을 통과하면 첫 돌파 보상을 받습니다. 광맥 원석은 광물 최대 5개와 배터리 12%를 줍니다.</p>`)}
function mineIcon(a){const shapes={hill:'<path d="M8 54 29 21 46 45 57 30 76 54Z" fill="#a8c58e" stroke="#6c8b71" stroke-width="3"/><circle cx="58" cy="18" r="9" fill="#f3d68c"/>',mushroom:'<path d="M31 39h23v22H31z" fill="#f7e8d5"/><path d="M15 40C15 7 66 7 68 40Z" fill="#e5aca0" stroke="#857e78" stroke-width="3"/><circle cx="31" cy="26" r="5" fill="#fff0db"/><circle cx="53" cy="30" r="6" fill="#fff0db"/>',crystal:'<path d="m19 52 4-28 15-12 15 16-5 31Z" fill="#b1a1df" stroke="#7c7f9b" stroke-width="3"/><path d="m47 58 4-23 15-5 4 24Z" fill="#a5d4e9" stroke="#7c7f9b" stroke-width="3"/><path d="m38 13 1 35-15-24" fill="#d3c8ef"/>',shell:'<path d="M41 59C-5 39 14 11 30 24 40 4 56 10 59 24 79 20 85 45 41 59Z" fill="#f2c1ba" stroke="#9a9293" stroke-width="3"/><path d="m24 31 17 25 2-31 13 8" fill="none" stroke="#d79fa0" stroke-width="3"/><circle cx="43" cy="46" r="8" fill="#fff1de"/>',snow:'<path d="M42 11v49M20 23l43 25M20 48l43-25" fill="none" stroke="#99b4d0" stroke-width="5" stroke-linecap="round"/><circle cx="42" cy="36" r="10" fill="#d9ebf1" stroke="#99b4d0" stroke-width="3"/>',star:'<path d="m42 10 9 16 19 3-14 14 3 19-17-9-17 9 3-19-14-14 19-3Z" fill="#f4d58b" stroke="#aa97aa" stroke-width="3"/>'};return`<svg class="mine-icon" viewBox="0 0 84 74" aria-hidden="true"><ellipse cx="42" cy="60" rx="32" ry="8" fill="${a.theme[1]}" opacity=".3"/>${shapes[a.icon]}</svg>`}
function allocateStat(key,amount=1){if(mode!=='town'||!statDefs.some(d=>d.key===key))return;const count=Math.min(freePoints(),Math.max(1,Math.floor(amount)),10000-save.stats[key]);if(count<=0)return;save.stats[key]+=count;persist();tone('upgrade');showStats();updateUI()}
function resetStats(){if(mode!=='town')return;save.stats={strength:0,dexterity:0,endurance:0,luck:0};persist();showStats();updateUI();toast('배분한 포인트를 모두 돌려받았습니다.')}
function useSkill(){if(mode!=='mine'||paused||skillCharge<100)return;skillCharge=0;skillRing=clock;const tx=Math.floor(p.x/T),ty=Math.floor(p.y/T),old=attackClock;for(let y=ty-1;y<=ty+1;y++)for(let x=tx-1;x<=tx+1;x++){const t=tile(x,y);if(t&&['dirt','rock','ore'].includes(t.k)){attackClock=0;dig(x,y)}}attackClock=Math.max(old,interval());skillCharge=0;tone('upgrade');toast('집중 굴착! 주변의 벽과 광맥을 한 번에 타격했습니다.');updateUI();persist()}

function showTown(){if(mode==='mine'){openSheet('town','마을로 귀환',`<p class="intro">지금 귀환하면 가방 속 광물을 모두 판매합니다. 아직 가지 않은 통로와 광맥은 이번 광산에 남습니다.</p><div class="stats"><div><b>${num(worth())}</b><small>예상 판매액 G</small></div><div><b>${bag.reduce((a,b)=>a+b,0)}</b><small>적재 광물</small></div></div><button class="primary" data-act="return">안전하게 귀환하기</button><button class="primary secondary" data-act="close">계속 탐험하기</button>`);return}openSheet('town','산골 마을',`<p class="intro">마을에서도 화면을 누르거나 드래그해 자유롭게 걸어 다닐 수 있습니다. 건물 앞으로 이동하면 이용 버튼이 나타납니다.</p><div class="cards">${buildings.map(b=>`<div class="card"><h3>${b.name}</h3><p>${{mine:'더 깊은 광산으로 출발',gear:'도구와 장비, 스킨, 소모품 구매',market:'광물 가치와 발견 도감 확인',quest:'채굴과 탐험 목표 보상',inn:'최대 8시간 자동 채굴 보상'}[b.id]}</p><button class="primary secondary" data-walk="${b.id}">걸어가기</button></div>`).join('')}</div>`)}
function showBag(){openSheet('bag','채굴 가방과 광물 도감',`<button class="primary secondary" data-act="supplies">소모품 사용하기</button><div class="stats"><div><b>${bag.reduce((a,b)=>a+b,0)} / ${bagMax()}</b><small>현재 적재</small></div><div><b>${num(worth())}</b><small>판매 예상 G</small></div></div>${ores.map((o,i)=>`<div class="row"><div><h3><i class="gem" style="background:${o.color}"></i>${o.name}${save.collection[o.name]?'':' <span class="tag">미발견</span>'}</h3><p>${mines.filter(a=>a.pool.includes(i)).map(a=>a.name).join(' / ')}<br>지하 ${o.min}층부터 / 기본 ${num(o.value)}G<br>누적 발견 ${num(save.collection[o.name]||0)}개 / 수집 등급 ${[10,30,100].filter(t=>(save.collection[o.name]||0)>=t).length}</p></div><b class="value">${bag[i]}개</b></div>`).join('')}<p class="note">광물별 누적 10개, 30개, 100개마다 영구 스탯 포인트 1을 얻습니다. 고품질 광맥에서는 광물이 최대 3개, 광맥 원석에서는 최대 5개 나옵니다. 가방의 남은 용량까지만 획득합니다. 귀환 시 정제 도구 수익 보너스가 적용됩니다.</p>${mode==='mine'?'<button class="primary" data-act="town">귀환하고 판매하기</button>':''}`)}
const quests=[{id:'first',name:'첫 번째 광부 수첩',desc:'광물 5개 채굴',goal:5,value:()=>save.total,reward:100},{id:'twenty',name:'가방을 채우는 즐거움',desc:'광물 20개 채굴',goal:20,value:()=>save.total,reward:220},{id:'return',name:'안전이 가장 중요해',desc:'마을로 1회 귀환',goal:1,value:()=>save.trips,reward:100},{id:'floor3',name:'깊어지는 발걸음',desc:'지하 3층 도달',goal:3,value:()=>save.best,reward:350},{id:'hundred',name:'믿음직한 광부',desc:'광물 100개 채굴',goal:100,value:()=>save.total,reward:800},{id:'floor5',name:'붉은 광맥을 찾아서',desc:'지하 5층 도달',goal:5,value:()=>save.best,reward:1200},{id:'types',name:'광물 수집가',desc:'광물 5종 발견',goal:5,value:()=>Object.values(save.collection).filter(n=>n>0).length,reward:1500},{id:'floor10',name:'깊은산의 개척자',desc:'지하 10층 도달',goal:10,value:()=>save.best,reward:3000}];
function showQuests(){openSheet('quest','광부 의뢰소',`<p class="intro">목표를 달성한 뒤 보상을 직접 받아 주세요. 의뢰 보상은 한 번만 지급됩니다.</p>${quests.map(q=>{const claimed=save.claims.includes(q.id),ready=q.value()>=q.goal;return`<div class="row"><div><h3>${q.name}</h3><p>${q.desc} <span class="value">${Math.min(q.goal,q.value())} / ${q.goal}</span><br>보상 ${num(q.reward)}G</p></div><button class="secondary" data-claim="${q.id}" ${claimed||!ready?'disabled':''}>${claimed?'수령 완료':ready?'보상 받기':'진행 중'}</button></div>`}).join('')}`)}
function claim(id){const q=quests.find(q=>q.id===id);if(!q||q.value()<q.goal||save.claims.includes(id))return;save.claims.push(id);save.coins+=q.reward;save.earned+=q.reward;record(`의뢰 완료: ${q.name}`);persist();tone('upgrade');showQuests();toast(`${num(q.reward)}G 보상을 받았습니다.`);updateUI()}
const escapeText=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function showSettings(){openSheet('settings','설정과 탐험 기록',`<p class="intro">같은 기기와 브라우저에서는 탐험과 성장이 자동 저장됩니다. 기기를 옮길 때에는 저장 파일을 내보낸 뒤 불러와 주세요.</p><div class="row"><div><h3>효과음</h3><p>채굴과 강화 소리</p></div><button class="secondary toggle" data-setting="sound">${save.settings.sound?'켜짐':'꺼짐'}</button></div><div class="row"><div><h3>진동</h3><p>지원하는 기기에서 짧게 진동</p></div><button class="secondary toggle" data-setting="vibrate">${save.settings.vibrate?'켜짐':'꺼짐'}</button></div><div class="row"><div><h3>드래그 감도</h3><p>낮을수록 천천히 조작합니다</p></div><input id="sensitivity" aria-label="드래그 감도" type="range" min="0.6" max="1.6" step="0.1" value="${save.settings.sensitivity}"></div><div class="row"><div><h3>전체 화면</h3><p>브라우저 지원 시 적용</p></div><button class="secondary" data-act="fullscreen">화면 확대</button></div><div class="cards" style="margin-top:16px"><div class="card"><h3>저장 파일</h3><p>${saveFailed?'저장 실패: 파일로 보관해 주세요.':'자동 저장 활성화'}</p><button class="primary secondary" data-act="export">내보내기</button></div><div class="card"><h3>다른 기기에서 이어하기</h3><p>현재 진행을 저장 파일로 교체합니다.</p><button class="primary secondary" data-act="import">불러오기</button></div></div><button class="primary secondary" data-act="stats">내 스탯과 성장 확인</button><button class="primary secondary" data-act="help">조작 방법 보기</button><div class="stats"><div><b>${num(save.total)}</b><small>누적 채굴</small></div><div><b>${save.best}층</b><small>최고 도달</small></div><div><b>${save.trips}</b><small>귀환 횟수</small></div></div><h3 style="font-size:13px">최근 탐험 기록</h3>${save.records.slice(0,8).map(r=>`<div class="row"><div><p>${escapeText(r.text)}</p><span class="note">${escapeText(r.date)}</span></div></div>`).join('')||'<p class="note">첫 탐험 기록을 남겨보세요.</p>'}<p class="note">깊은산 채굴기 0.7.1 / 모바일 웹<br>참고 자료: <a href="https://punkland.io/game/detail/17464" target="_blank" rel="noopener">뒷산에서 광물캐기</a>, <a href="https://play.google.com/store/apps/details?id=com.mpmaker.GoldMountain" target="_blank" rel="noopener">뒷산에서 보석캐기 공식 소개</a><br>이 게임의 그래픽과 코드는 독자 제작했습니다.</p>`)}
function showHelp(){openSheet('help','손끝으로 탐험하는 깊은산',`<p class="intro">산골 마을의 새 광부님, 환영합니다.</p><div class="row"><div><h3>화면 어디서나 드래그</h3><p>손가락을 댄 곳이 조이스틱이 됩니다. 원하는 방향으로 끌어 걷고, 떼면 멈춥니다.</p></div></div><div class="row"><div><h3>한 번 눌러 목적지 지정</h3><p>길이나 건물을 누르면 경로를 찾아갑니다. 광석을 누르면 다가가 자동으로 굴착합니다.</p></div></div><div class="row"><div><h3>채굴하고, 귀환하고, 장착하기</h3><p>가방이 차거나 배터리가 부족하면 귀환하세요. 광물 판매액으로 상점에서 아이템을 사고 성장 화면에서 장착합니다.</p></div></div><div class="row"><div><h3>아래층 통로 찾기</h3><p>사다리 위에 서면 다음 층 버튼이 나타납니다. 지도에서 탐험한 길과 발견한 사다리를 확인하세요.</p></div></div><div class="row"><div><h3>광산 선택과 스탯 성장</h3><p>광산 입구에서 6개 광산의 해금 조건을 확인하세요. 하단 성장 화면에서 레벨업 포인트를 배분할 수 있습니다.</p></div></div><div class="row"><div><h3>광맥을 모아 집중 굴착</h3><p>광맥을 채굴할 때마다 굴착이 12%씩 충전됩니다. 100%에서 오른쪽 굴착 버튼을 누르면 주변 8칸을 한 번씩 타격합니다.</p></div></div><p class="note">PC에서는 WASD 또는 방향키로 이동하고, E 또는 Space로 상호작용합니다. 메뉴를 열거나 다른 앱으로 전환하면 직접 탐험은 멈추며, 방치 작업소는 계속 보상을 모읍니다.</p><button class="primary" data-act="close">마을 둘러보기</button>`)}
function showMap(){openSheet('map',mode==='town'?'산골 마을 지도':`${areaInfo().name} ${floor}층 지도`,`<p class="intro">${mode==='town'?'건물 이름을 눌러 이동할 수 있습니다.':'밝혀진 통로와 광맥을 표시합니다. 밝은 점이 현재 위치입니다.'}</p><canvas id="minimap" class="mapcanvas" width="500" height="500" aria-label="전체 탐험 지도"></canvas>${mode==='town'?'<div class="cards" style="margin-top:12px">'+buildings.map(b=>`<button class="secondary" data-walk="${b.id}">${b.name}</button>`).join('')+'</div>':'<p class="note">초록: 통로 / 노랑: 사다리 / 금빛: 광석 / 흰색: 현재 위치</p>'}`);const m=$('minimap'),q=m.getContext('2d');q.fillStyle='#e6ebdc';q.fillRect(0,0,500,500);if(mode==='town'){const s=450/1100;for(const b of buildings){q.fillStyle=b.roof;q.fillRect(25+b.x*s,25+b.y*s,b.w*s,b.h*s);q.fillStyle='#6a7c68';q.font='12px system-ui';q.fillText(b.name,25+b.x*s,20+b.y*s)}q.fillStyle='#ffdf92';q.beginPath();q.arc(25+p.x*s,25+p.y*s,5,0,7);q.fill()}else{const s=Math.min(470/gw,470/gh),ox=(500-gw*s)/2,oy=(500-gh*s)/2;for(let y=0;y<gh;y++)for(let x=0;x<gw;x++)if(discovered[y][x]){const t=tile(x,y);q.fillStyle=t.k==='stairs'?'#f1d080':t.k==='ore'?ores[t.ore].color:t.k==='air'?'#568a74':'#2c4840';q.fillRect(ox+x*s,oy+y*s,s-1,s-1)}q.fillStyle='#fff3cf';q.beginPath();q.arc(ox+p.x/T*s,oy+p.y/T*s,5,0,7);q.fill()}}
function exportSave(){persist();const payload={format:'deepmine-backup',save,run:mode==='mine'?{floor,area,skillCharge,snackUntil,grid,gw,gh,p,energy,bag,runMined,elapsed,enemies,discovered}:null};const url=URL.createObjectURL(new Blob([JSON.stringify(payload)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='깊은산_저장파일.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('저장 파일을 내보냈습니다.')}
function validRun(r){if(!r||!Number.isInteger(r.floor)||r.floor<1||r.floor>10000||r.gw!==34||r.gh!==42||!Array.isArray(r.grid)||r.grid.length!==42||!r.grid.every(row=>Array.isArray(row)&&row.length===34&&row.every(t=>t&&['air','dirt','rock','ore','stairs','charger','chest','bedrock'].includes(t.k)&&((t.k!=='ore')||(Number.isInteger(t.ore)&&t.ore>=0&&t.ore<ores.length))&&(!['ore','dirt','rock'].includes(t.k)||(Number.isFinite(t.hp)&&t.hp>0)))))return false;if(!r.p||!Number.isFinite(r.p.x)||!Number.isFinite(r.p.y)||r.p.x<42||r.p.x>33*42||r.p.y<42||r.p.y>41*42||!Number.isFinite(r.energy)||r.energy<=0||r.energy>100||!Array.isArray(r.bag)||(r.bag.length!==7&&r.bag.length!==ores.length)||!r.bag.every(n=>Number.isInteger(n)&&n>=0)||!Number.isFinite(r.runMined)||r.runMined<0||!Number.isFinite(r.elapsed)||r.elapsed<0)return false;return Array.isArray(r.discovered)&&r.discovered.length===42&&r.discovered.every(row=>Array.isArray(row)&&row.length===34)&&Array.isArray(r.enemies)&&r.enemies.every(e=>Number.isFinite(e.x)&&Number.isFinite(e.y)&&Number.isFinite(e.hp)&&e.hp>0)}
function restoreRun(r){if(!validRun(r))return false;({floor,area,skillCharge,snackUntil,grid,gw,gh,p,energy,bag,runMined,elapsed,enemies,discovered}=r);area=mines.some(a=>a.id===r.area)?r.area:'meadow';snackUntil=Number.isFinite(r.snackUntil)?Math.min(r.elapsed+60,r.snackUntil):0;skillCharge=Number.isFinite(r.skillCharge)?clamp(r.skillCharge,0,100):0;bag=ores.map((_,i)=>bag[i]||0);runMilestone=level();mode='mine';cam={x:p.x,y:p.y};return true}
async function importSave(){const inputFile=document.createElement('input');inputFile.type='file';inputFile.accept='.json,application/json';inputFile.onchange=async()=>{try{const f=inputFile.files[0];if(!f||f.size>4000000)throw Error();const data=JSON.parse(await f.text());if(data.format!=='deepmine-backup')throw Error();const checked=validate(data.save);if(data.run&&!validRun(data.run))throw Error();openSheet('importConfirm','저장 파일을 불러올까요?',`<p class="intro">현재 기기의 진행을 광부 레벨 ${1+Math.floor(Math.sqrt(checked.xp/24))}, 보유 ${num(checked.coins)}G의 저장 파일로 바꿉니다.</p><button class="primary" id="confirmImport">이 저장 파일로 이어하기</button><button class="primary secondary" data-act="settings">취소</button>`);$('confirmImport').onclick=()=>{save=checked;mode='town';p={x:550,y:620,face:1,angle:0};cam={x:p.x,y:p.y};bag=ores.map(()=>0);if(data.run)restoreRun(data.run);closeSheet();persist();updateUI();toast('저장 파일을 불러왔습니다.')}}catch{toast('올바른 깊은산 저장 파일이 아닙니다. 현재 진행은 유지됩니다.')}};inputFile.click()}
const panels={shop:showShop,idle:showIdle,town:showTown,stats:showStats,gear:showGear,bag:showBag,quest:showQuests,settings:showSettings};document.querySelectorAll('[data-panel]').forEach(b=>b.onclick=()=>panels[b.dataset.panel]());$('close').onclick=closeSheet;$('shade').addEventListener('click',e=>{if(e.target===$('shade'))closeSheet()});$('sheetBody').addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.buy)buyItem(b.dataset.buy);if(b.dataset.equip)equip(b.dataset.equip);if(b.dataset.use)useSupply(b.dataset.use);if(b.dataset.idle)beginIdle(b.dataset.idle);if(b.dataset.growth){growthTab=b.dataset.growth;showStats()}if(b.dataset.shop){shopTab=b.dataset.shop;showShop()}if(b.dataset.stat)allocateStat(b.dataset.stat,Number(b.dataset.amount)||1);if(b.dataset.mine){selectedMine=b.dataset.mine;showMine()}if(b.dataset.claim)claim(b.dataset.claim);if(b.dataset.setting){save.settings[b.dataset.setting]=!save.settings[b.dataset.setting];persist();showSettings();tone('upgrade')}if(b.dataset.walk){const n=buildings.find(n=>n.id===b.dataset.walk);closeSheet();if(mode==='town')townPath(n.door.x,n.door.y)}const acts={shop:showShop,supplies:showSupplies,idle:showIdle,idleClaim:()=>claimIdle(),idleStop:()=>claimIdle(true),idleRefresh:showIdle,close:closeSheet,stats:showStats,resetStats:resetStats,gear:showGear,bag:showBag,town:showTown,quest:showQuests,settings:showSettings,help:showHelp,return:()=>{closeSheet();returnTown()},start:()=>start(Number($('floorSelect')?.value)||depthFor(selectedMine),selectedMine),export:exportSave,import:importSave,fullscreen:async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await $('app').requestFullscreen()}catch{toast('이 브라우저는 전체 화면을 지원하지 않습니다.')}}};if(acts[b.dataset.act])acts[b.dataset.act]()});$('sheetBody').addEventListener('input',e=>{if(e.target.id==='sensitivity'){save.settings.sensitivity=Number(e.target.value);persist()}});
$('supplies').onclick=showSupplies;$('idlebutton').onclick=showIdle;$('skill').onclick=useSkill;
$('home').onclick=()=>mode==='mine'?showTown():showMap();$('mapbutton').onclick=showMap;$('auto').onclick=()=>{save.settings.auto=!save.settings.auto;persist();updateUI();toast(save.settings.auto?'가까운 광석을 자동으로 채굴합니다.':'자동 채굴을 껐습니다. 광석을 직접 선택해 채굴하세요.')};$('pause').onclick=()=>{if(openPanel)return;manualPause=true;openSheet('pause','잠시 쉬어 가세요','<p class="intro">이동과 배터리 소모가 멈췄습니다.</p><button class="primary" id="resumeButton">계속 탐험하기</button>');$('resumeButton').onclick=()=>{manualPause=false;closeSheet()}};
$('interact').onclick=interact;$('interact').addEventListener('pointerdown',e=>{if(mode==='mine'&&!paused){actionHeld=true;e.target.setPointerCapture?.(e.pointerId)}});for(const ev of ['pointerup','pointercancel','lostpointercapture'])$('interact').addEventListener(ev,()=>actionHeld=false);
function point(e){const r=cv.getBoundingClientRect();return {x:(e.clientX-r.left-vw/2)/zoom+cam.x,y:(e.clientY-r.top-vh/2)/zoom+cam.y}}
function down(e){if(paused||input||e.button>0||e.target.closest('button,nav,#shade,input,select,a'))return;e.preventDefault();route=[];goal=null;const r=cv.getBoundingClientRect();input={id:e.pointerId,x:e.clientX,y:e.clientY,cx:e.clientX-r.left,cy:e.clientY-r.top,dx:0,dy:0,drag:false,born:clock};try{cv.setPointerCapture(e.pointerId)}catch{}}
function pointerMove(e){if(!input||input.id!==e.pointerId)return;const dx=e.clientX-input.x,dy=e.clientY-input.y;if(Math.hypot(dx,dy)>8){input.drag=true;input.dx=dx;input.dy=dy;const r=cv.getBoundingClientRect();$('joy').style.display='block';$('joy').style.left=input.cx-48+'px';$('joy').style.top=input.cy-48+'px';const len=Math.hypot(dx,dy),s=Math.min(30,len)/(len||1);$('joy').firstElementChild.style.transform=`translate(${dx*s}px,${dy*s}px)`}}
function up(e){if(!input||e.pointerId!==input.id)return;const prev=input;input=null;$('joy').style.display='none';if(!prev.drag&&!paused){const q=point(e);if(mode==='town')townPath(q.x,q.y);else pathTo(Math.floor(q.x/T),Math.floor(q.y/T))}}
document.addEventListener('pointerdown',down,{passive:false});document.addEventListener('pointermove',pointerMove,{passive:false});document.addEventListener('pointerup',up);document.addEventListener('pointercancel',e=>{if(input?.id===e.pointerId)resetInput()});cv.addEventListener('lostpointercapture',e=>{if(input?.id===e.pointerId)resetInput()});cv.addEventListener('contextmenu',e=>e.preventDefault());
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='Escape'){if(openPanel){manualPause=false;closeSheet()}else $('pause').click();return}if(paused)return;const k=e.key.toLowerCase();if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' ','e'].includes(k)){e.preventDefault();if(k===' '||k==='e'){if(!e.repeat)interact()}else{keys.add(k);route=[];goal=null}}});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));
function suspend(){persist();resetInput();if(!paused){manualPause=true;openSheet('pause','탐험이 일시정지되었습니다','<p class="intro">자리를 비운 동안 배터리는 소모되지 않습니다.</p><button class="primary" id="resumeButton">이어서 플레이</button>');$('resumeButton').onclick=()=>{manualPause=false;closeSheet()}}}document.addEventListener('visibilitychange',()=>{if(document.hidden)suspend()});window.addEventListener('blur',suspend);window.addEventListener('pagehide',persist);
function updateUI(){near=nearest();$('app').dataset.mode=mode;$('coins').textContent=num(save.coins);$('area').textContent=mode==='town'?'지상 기지 / 0.7.1':`${areaInfo().name} / 지하 ${floor}층`;$('energyText').textContent=Math.ceil(energy)+'%';$('energyBar').style.width=energy+'%';$('energyBar').style.background=energy<20?'#e59176':'#91d4ad';const count=bag.reduce((a,b)=>a+b,0);$('bagText').textContent=count+' / '+bagMax();$('bagBar').style.width=count/bagMax()*100+'%';$('level').textContent=level();$('skill').textContent=skillCharge>=100?'집중 굴착!':`굴착 ${Math.floor(skillCharge)}%`;$('skill').disabled=mode!=='mine'||skillCharge<100;$('skill').style.display=mode==='mine'?'block':'none';$('skill').classList.toggle('ready',skillCharge>=100);const sb=document.querySelector('[data-panel="stats"]');if(sb)sb.innerHTML='성장'+(freePoints()?` <b class="badge">${freePoints()}</b>`:'');$('home').textContent=mode==='mine'?'마을 귀환':'마을 지도';$('auto').classList.toggle('on',save.settings.auto);$('auto').setAttribute('aria-pressed',String(save.settings.auto));$('auto').innerHTML='자동 채굴<br><small>'+(save.settings.auto?'켜짐':'꺼짐')+'</small>';$('interact').innerHTML=(near?.action||(mode==='town'?'광산 선택':'채굴'))+' <span>'+(mode==='town'?'↗':'⛏')+'</span>';const ready=quests.filter(q=>q.value()>=q.goal&&!save.claims.includes(q.id)).length;const qbutton=document.querySelector('[data-panel="quest"]');qbutton.innerHTML='의뢰'+(ready?` <b class="badge">${ready}</b>`:'');$('objectiveText').textContent=mode==='town'?(near?near.name+' 앞입니다. 아래 버튼으로 이용하세요.':'광산 선택 → 채굴 → 귀환 후 판매'):(count>=bagMax()?'가방이 가득 찼습니다. 귀환해 판매하세요.':energy<20?'배터리가 부족합니다. 귀환을 준비하세요.':`사다리를 찾아 아래층으로 / 가방 가치 ${num(worth())}G`);$('contextHint').textContent=route.length?'목적지로 이동 중 / 드래그하면 직접 조작':mode==='town'?'건물을 누르면 입구까지 이동합니다.':near?.id==='stairs'?'아래층 통로를 발견했습니다.': '광석을 누르면 접근 후 채굴 / 어디서나 드래그 이동';document.querySelector('[data-panel="town"]').classList.toggle('active',mode==='town')}
function rr(x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=1.5;c.stroke()}}
function ellipse(x,y,rx,ry,color){c.fillStyle=color;c.beginPath();c.ellipse(x,y,rx,ry,0,0,Math.PI*2);c.fill()}
function poly(points,fill,stroke){c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(x,y):c.moveTo(x,y));c.closePath();if(fill){c.fillStyle=fill;c.fill()}if(stroke){c.strokeStyle=stroke;c.lineWidth=2;c.stroke()}}
function label(text,x,y,color='#eae8cf',size=12){c.font=`600 ${size}px system-ui`;c.textAlign='center';c.fillStyle=color;c.fillText(text,x,y)}
function tree(x,y,s=1){c.save();c.translate(x,y);c.scale(s,s);ellipse(6,17,25,7,'#263c3622');rr(-4,-13,8,35,1,'#765b43');poly([[-25,3],[0,-49],[25,3]],'#4f7164');poly([[-20,-13],[0,-58],[20,-13]],'#638878');poly([[0,-58],[0,3],[25,3]],'#405e55');c.restore()}
